  async function renderRemoteTitle(item,generation){app.innerHTML=remoteHero(item)+'<p class="catalog-status">Loading title details…</p>';try{const data=await metadata('/api/title-details',{type:item.type==='series'?'tv':'movie',id:item.tmdbId});if(generation!==routeGeneration)return;const detail=remember(data);Object.assign(item,detail);app.innerHTML=remoteHero(item)+(item.type==='series'?seasonShell(item):'')+extras(data);outlaw?.enhanceTitle(item);if(item.type==='series')bindSeasons(item,generation);normalizeLinks()}catch(e){if(generation===routeGeneration){app.innerHTML=remoteHero(item)+'<section class="catalog-section"><p>'+escape(e.message)+'</p><button id="retryDetails" class="subtle-pill">Retry details</button></section>';$('#retryDetails').onclick=()=>renderRemoteTitle(item,generation)}}}
  function oldSeasonShell(item){const seasons=(item.seasons||[]).filter(s=>Number(s.seasonNumber)>0);return '<section class="episodes-section"><div class="row-heading"><h2>Episodes</h2><select id="remoteSeason" aria-label="Choose season">'+(seasons.length?seasons:[{seasonNumber:1,name:'Season 1'}]).map(s=>'<option value="'+s.seasonNumber+'">'+escape(s.name||'Season '+s.seasonNumber)+'</option>').join('')+'</select></div><div id="remoteEpisodes"></div></section>'}
  function oldBindSeasons(item,generation){const select=$('#remoteSeason');select.onchange=()=>loadSeason(item,Number(select.value),generation);loadSeason(item,Number(select.value),generation)}
  const episodeSort=new Map();
  function seasonShell(item){const seasons=(item.seasons||[]).filter(s=>Number(s.seasonNumber)>0);const selected=Number(logicalPath().split('/')[3])||Number(new URLSearchParams(location.search).get('season'))||Number(read('bogart.season.'+item.id,item.id==='the-traitors'?5:1));const current=seasons.some(s=>s.seasonNumber===selected)?selected:seasons[0]?.seasonNumber||1;return '<section class="episodes-section"><div class="row-heading"><h2>Episodes</h2><div class="episode-toolbar"><button class="episode-sort" id="remoteSort" aria-label="Sort episodes">'+(episodeSort.get(item.id)?'↓ Newest':'↑ Oldest')+'</button><div class="season-dropdown"><input id="remoteSeason" type="hidden" value="'+current+'"><button class="season-trigger" aria-haspopup="listbox" aria-expanded="false">Season '+current+'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 9 6 6 6-6"/></svg></button><div class="season-menu" role="listbox" aria-label="Choose season" hidden>'+seasons.map(s=>'<button role="option" aria-selected="'+(s.seasonNumber===current)+'" data-season="'+s.seasonNumber+'">'+(art(s.poster)?'<img src="'+art(s.poster)+'" alt="">':'')+'<span>'+escape(s.name||'Season '+s.seasonNumber)+'<small>'+s.episodeCount+' episodes</small></span></button>').join('')+'</div></div></div></div><div class="episode-rail"><button class="episode-edge" data-scroll="-1" aria-label="Scroll episodes left">‹</button><div id="remoteEpisodes"></div><button class="episode-edge" data-scroll="1" aria-label="Scroll episodes right">›</button></div></section>'}
  function bindSeasons(item,generation){const select=$('#remoteSeason'),menu=$('.season-menu'),trigger=$('.season-trigger');const close=()=>{menu.hidden=true;trigger.setAttribute('aria-expanded','false')};trigger.onclick=()=>{menu.hidden=!menu.hidden;menu.style.top='calc(100% + 10px)';menu.style.bottom='auto';if(!menu.hidden&&menu.getBoundingClientRect().bottom>innerHeight-15){menu.style.top='auto';menu.style.bottom='calc(100% + 10px)'}trigger.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('[aria-selected=true]')?.focus()};menu.querySelectorAll('[data-season]').forEach(b=>b.onclick=()=>{select.value=b.dataset.season;trigger.firstChild.textContent='Season '+select.value;menu.querySelectorAll('button').forEach(x=>x.setAttribute('aria-selected',String(x===b)));write('bogart.season.'+item.id,Number(select.value));close();trigger.focus();loadSeason(item,Number(select.value),generation)});menu.onkeydown=e=>{const buttons=[...menu.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close();trigger.focus()}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}};const outside=e=>{if(!trigger.isConnected){document.removeEventListener('click',outside);return}if(!e.target.closest('.season-dropdown'))close()};document.addEventListener('click',outside);$('#remoteSort').onclick=()=>{episodeSort.set(item.id,!episodeSort.get(item.id));$('#remoteSort').textContent=episodeSort.get(item.id)?'↓ Newest':'↑ Oldest';loadSeason(item,Number(select.value),generation)};loadSeason(item,Number(select.value),generation)}
  async function seasonEpisodes(item,season){const data=await metadata('/api/tv-season',{id:item.tmdbId||item.id,season});return (data.episodes||[]).map(ep=>({...ep,number:Number(ep.number),still:art(ep.still)}))}
  async function loadSeason(item,season,generation){const host=$('#remoteEpisodes');if(!host)return;host.innerHTML='<p class="catalog-status">Loading episodes…</p>';const request=host.dataset.request=String(Date.now())+Math.random();try{const rows=await seasonEpisodes(item,season);if(generation!==routeGeneration||!host.isConnected||host.dataset.request!==request||Number($('#remoteSeason').value)!==season)return;item.season=season;item.seasonEpisodeCount=rows.length;host.innerHTML='<div class="episode-row">'+(episodeSort.get(item.id)?[...rows].reverse():rows).map(ep=>{const owned=item.id==='the-traitors'&&season===5?episodes.find(e=>e.n===ep.number&&e.video):null;const href='/watch/'+item.id+'/'+season+'/'+ep.number;return '<article class="episode-card available"><a class="episode-art" href="'+href+'" aria-label="Play S'+season+' E'+ep.number+': '+escape(ep.title)+'">'+(ep.still?'<img src="'+ep.still+'" alt="" loading="lazy">':'<span class="no-poster">Episode '+ep.number+'</span>')+'<span class="episode-number">E'+ep.number+'</span>'+(ep.runtime?'<span class="episode-runtime">'+ep.runtime+'m</span>':'')+'<span class="hover-play">'+icon('play')+'</span>'+'</a><h3>'+escape(ep.title)+'</h3><p>'+escape(ep.description||'')+'</p></article>'}).join('')+'</div>';if(!rows.length)host.innerHTML='<p class="catalog-status">No episodes listed for this season.</p>';document.querySelector('.detail-main .play-action')?.setAttribute('href',watchPath(item));outlaw?.enhanceEpisodes(item,season,rows,host);normalizeLinks()}catch(e){if(generation===routeGeneration&&host.isConnected){host.innerHTML='<p class="catalog-status">'+escape(e.message)+'</p><button class="subtle-pill">Retry episodes</button>';host.querySelector('button').onclick=()=>loadSeason(item,season,generation)}}}
  streamPlayer.getEpisodeData=async input=>{const item=find(input.catalogId);if(!item)return null;return {seasons:item.seasons||[],loadSeason:season=>seasonEpisodes(item,season)}};
  streamPlayer.onSelectEpisode=(season,episode)=>navigate('/watch/'+streamPlayer.item.catalogId+'/'+season+'/'+episode);streamPlayer.changeEpisode=function(offset){const n=this.item.episode+offset;if(n<1||this.item.seasonEpisodeCount&&n>this.item.seasonEpisodeCount)return;this.onSelectEpisode(this.item.season,n)};
  async function enrichOwned(item,generation){try{const data=await metadata('/api/title-details',{type:item.type==='series'?'tv':'movie',id:item.tmdbId});if(generation!==routeGeneration)return;if(art(data.logo)){item.logo=art(data.logo);app.querySelector('.detail-main .title-logo').outerHTML=logo(item)}const wrapper=document.createElement('div');wrapper.className='title-extras';wrapper.innerHTML=extras(data);app.append(wrapper);Object.assign(item,{cast:data.cast||[],trailers:data.trailers||[],companies:data.companies||[],directorPeople:data.directorPeople||[],budget:data.budget,revenue:data.revenue});outlaw?.enhanceTitle(item);if(item.type==='series'){item.seasons=data.seasons||[];const old=app.querySelector('.episodes-section');if(old){old.outerHTML=seasonShell(item);const select=$('#remoteSeason');select.value='5';bindSeasons(item,generation);outlaw?.enhanceTitle(item)}}normalizeLinks()}catch{/* Native uploaded playback remains available when metadata fails. */}}

